          fontFamily: 'serif',
          letterSpacing: 0.02,
          paragraphSpacing: 0.9,
          pageWidth: 'comfortable',
          autoHideChrome: false,
          highlightColor: 'amber',
          speechRate: 1,
          speechVoice: '',
          textAlign: 'justify',
