        customBooks: [],
        progress: {},
        bookmarks: [],
        highlights: [],
        stats: { days: {}, goalMinutes: DEFAULT_WEEKLY_GOAL_MINUTES, byBook: {} },
        lastBookId: null,
        lastReadAt: 0,
        shelfSort: 'recent',
        shelfView: 'grid',
